#!/usr/bin/env bash
# Assembles and packages the Battuta Linux release (Linux port PR 10).
#
# Stages the FHS payload from three sources —
#   1. self-contained .NET publish of Battuta.Linux (linux-x64),
#   2. release Rust builds (battuta-gpui, battuta-inputd, libbattuta_audio.so),
#   3. build-time PCM products generated by battuta-audio-prep and verified
#      against the shared audio tree (plan §6.2.3: input hashes, output
#      count, sample rate, channels) —
# then produces the release artifacts:
#   - battuta_<version>_amd64.deb        (dpkg-deb; skipped without dpkg-deb)
#   - battuta-<version>-1.x86_64.rpm     (rpmbuild; skipped without rpmbuild)
#   - Battuta-Linux-<version>-linux-x64.tar.gz  (portable FHS payload)
#   - Battuta-Linux-<version>-linux-x64.spdx.json (SPDX 2.3 SBOM)
#   - SHA256SUMS (+ ASCII-armored detached signatures when
#     BATTUTA_RELEASE_SIGN_KEY is set)
#
# Usage:
#   scripts/build-linux-package.sh --version 1.2.3 [--out DIR] [--skip-publish]
#
# --skip-publish reuses an existing staged payload (payload.tgz) instead of
# rebuilding .NET/Rust/prep — useful when only package metadata changes.

set -euo pipefail

usage() {
    echo "usage: build-linux-package.sh --version <semver> [--out DIR] [--skip-publish]" >&2
    exit 2
}

VERSION=""
OUT_DIR=""
SKIP_PUBLISH=0
while [[ $# -gt 0 ]]; do
    case "$1" in
        --version) VERSION="${2:-}"; shift 2 ;;
        --out) OUT_DIR="${2:-}"; shift 2 ;;
        --skip-publish) SKIP_PUBLISH=1; shift ;;
        *) usage ;;
    esac
done
[[ "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$ ]] || usage

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
linux_root="$repo_root/BattutaLinux"
packaging_root="$linux_root/packaging"
out_dir="${OUT_DIR:-$linux_root/artifacts}"
work_dir="$out_dir/work-$VERSION"
stage_dir="$work_dir/payload"
release_date="$(date +%F)"

for tool in dotnet cargo node python3 sha256sum; do
    command -v "$tool" >/dev/null 2>&1 || { echo "error: $tool is required" >&2; exit 1; }
done
have() { command -v "$1" >/dev/null 2>&1; }

expected_products=237   # 151 MP3 + 86 WAV canonical recordings (plan §14)

mkdir -p "$out_dir"
rm -rf "$work_dir"
mkdir -p "$stage_dir"

echo "==> Battuta Linux packaging $VERSION ($release_date)"

if [[ "$SKIP_PUBLISH" == 1 ]]; then
    payload_tar="$out_dir/Battuta-Linux-$VERSION-linux-x64-payload.tgz"
    [[ -f "$payload_tar" ]] || { echo "error: --skip-publish needs $payload_tar" >&2; exit 1; }
    mkdir -p "$stage_dir"
    tar xzf "$payload_tar" -C "$stage_dir"
    app_dir="$stage_dir/usr/lib/battuta/bin"
else
    # ---- 1. .NET self-contained publish ---------------------------------
    app_dir="$stage_dir/usr/lib/battuta/bin"
    echo "==> dotnet publish (linux-x64, self-contained)"
    dotnet publish "$linux_root/src/Battuta.Linux/Battuta.Linux.csproj" \
        --configuration Release \
        --runtime linux-x64 \
        --self-contained true \
        -p:Version="$VERSION" \
        -p:ContinuousIntegrationBuild="$([[ "${CI:-}" == true ]] && echo true || echo false)" \
        --output "$app_dir"
    rm -f "$app_dir"/*.pdb "$app_dir"/*.d

    # ---- 2. Native artifacts -------------------------------------------
    echo "==> cargo build --release"
    cargo build --release --manifest-path "$linux_root/native/Cargo.toml" \
        -p battuta-inputd -p battuta-audio
    install -m 0755 "$linux_root/native/target/release/battuta-inputd" "$app_dir/battuta-inputd"
    install -m 0755 "$linux_root/native/target/release/libbattuta_audio.so" "$app_dir/libbattuta_audio.so"

    cargo build --locked --release --manifest-path "$linux_root/gpui/Cargo.toml"
    install -m 0755 "$linux_root/gpui/target/release/battuta-gpui" "$app_dir/battuta-gpui"
    install -m 0644 "$linux_root/gpui/vendor/gpui/LICENSE-APACHE" "$app_dir/GPUI-LICENSE-APACHE"

    # ---- 3. Build-time PCM products + verification (plan §6.2.3) --------
    echo "==> battuta-audio-prep products"
    prep_binary="$linux_root/native/target/release/battuta-audio-prep"
    if [[ ! -x "$prep_binary" ]]; then
        cargo build --release --manifest-path "$linux_root/native/Cargo.toml" -p battuta-audio-prep
    fi
    "$prep_binary" \
        --source "$repo_root/shared/audio/builtin" \
        --out "$app_dir/Assets/Sounds" >/dev/null

    "$prep_binary" --help >/dev/null 2>&1 || true
    python3 - "$app_dir/Assets/Sounds/manifest.json" "$app_dir/Assets/Sounds" "$expected_products" <<'PY'
import hashlib
import json
import pathlib
import sys

manifest_path, product_root, expected = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]), int(sys.argv[3])
manifest = json.loads(manifest_path.read_text())
assert manifest["sample_rate"] == 48000, "product sample rate must be 48 kHz"
assert manifest["channels"] == 1, "products must be mono"
products = manifest["products"]
if len(products) != expected:
    sys.exit(f"expected {expected} products, manifest lists {len(products)}")
for record in products:
    output = product_root / record["output"]
    digest = hashlib.sha256(output.read_bytes()).hexdigest()
    if digest != record["output_sha256"]:
        sys.exit(f"product hash mismatch: {record['output']}")
print(f"verified {len(products)} PCM products (48 kHz mono, hashes match manifest)")
PY

    # ---- 4. Desktop integration files ----------------------------------
    echo "==> staging FHS payload"
    install -d "$stage_dir/usr/bin"
    cat > "$stage_dir/usr/bin/battuta" <<'WRAPPER'
#!/bin/sh
# Battuta UI entry point (packaged layout: /usr/lib/battuta/bin).
LD_LIBRARY_PATH="/usr/lib/battuta/bin${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
export LD_LIBRARY_PATH
exec /usr/lib/battuta/bin/battuta-gpui "$@"
WRAPPER
    chmod 0755 "$stage_dir/usr/bin/battuta"

    install -d "$stage_dir/usr/lib/systemd/system"
    install -m 0644 "$packaging_root/systemd/battuta-inputd.service" "$stage_dir/usr/lib/systemd/system/"
    install -m 0644 "$packaging_root/systemd/battuta-inputd.socket" "$stage_dir/usr/lib/systemd/system/"

    install -d "$stage_dir/usr/lib/sysusers.d" "$stage_dir/usr/lib/tmpfiles.d"
    install -m 0644 "$packaging_root/sysusers/battuta-inputd.conf" "$stage_dir/usr/lib/sysusers.d/"
    install -m 0644 "$packaging_root/tmpfiles/battuta-inputd.conf" "$stage_dir/usr/lib/tmpfiles.d/"

    install -d "$stage_dir/usr/share/polkit-1/actions"
    install -m 0644 "$packaging_root/polkit/io.github.wormforce.Battuta.Input1.policy" \
        "$stage_dir/usr/share/polkit-1/actions/"

    # D-Bus system-bus policy: without it the broker cannot claim its bus
    # name and dies on startup (RequestName AccessDenied).
    install -d "$stage_dir/usr/share/dbus-1/system.d"
    install -m 0644 "$packaging_root/dbus-1/system.d/io.github.wormforce.Battuta.Input1.conf" \
        "$stage_dir/usr/share/dbus-1/system.d/"

    install -d "$stage_dir/usr/share/applications" "$stage_dir/usr/share/metainfo" \
        "$stage_dir/usr/share/mime/packages"
    install -m 0644 "$packaging_root/desktop/io.github.wormforce.Battuta.desktop" \
        "$stage_dir/usr/share/applications/"
    install -m 0644 "$packaging_root/appstream/io.github.wormforce.Battuta.metainfo.xml" \
        "$stage_dir/usr/share/metainfo/"
    install -m 0644 "$packaging_root/mime/io.github.wormforce.Battuta.xml" \
        "$stage_dir/usr/share/mime/packages/"

    install -d "$stage_dir/usr/share/icons/hicolor"
    cp -a "$packaging_root/icons/hicolor/." "$stage_dir/usr/share/icons/hicolor/"

    install -d "$stage_dir/usr/share/doc/battuta"
    install -m 0644 \
        "$repo_root/LICENSE" \
        "$repo_root/THIRD_PARTY_NOTICES.md" \
        "$repo_root/PRIVACY.md" \
        "$repo_root/shared/licenses/AUDIO_SOURCES.md" \
        "$repo_root/shared/contracts/SOUND_PACK_FORMAT.md" \
        "$stage_dir/usr/share/doc/battuta/"

    # Rewrite the AppStream release entry so the payload never ships a
    # placeholder (validated with appstreamcli when available).
    metainfo="$stage_dir/usr/share/metainfo/io.github.wormforce.Battuta.metainfo.xml"
    sed -i "s|<release version=\"@RELEASE_VERSION@\" date=\"1970-01-01\" />|<release version=\"$VERSION\" date=\"$release_date\" />|" "$metainfo"
    grep -q "version=\"$VERSION\"" "$metainfo" || {
        echo "error: metainfo release rewrite failed" >&2; exit 1;
    }
    if have appstreamcli; then
        appstreamcli validate --no-net "$metainfo" || { echo "error: AppStream validation failed" >&2; exit 1; }
    fi
    if have desktop-file-validate; then
        desktop-file-validate "$stage_dir/usr/share/applications/io.github.wormforce.Battuta.desktop" \
            || { echo "error: desktop file validation failed" >&2; exit 1; }
    fi
fi

installed_size_kb="$(du -sk "$stage_dir" | cut -f1)"

# ---- 5. Portable payload tarball ---------------------------------------
echo "==> portable tarball"
payload_tar="$out_dir/Battuta-Linux-$VERSION-linux-x64-payload.tgz"
tar czf "$payload_tar" -C "$stage_dir" .
portable_tar="$out_dir/Battuta-Linux-$VERSION-linux-x64.tar.gz"
tar czf "$portable_tar" -C "$stage_dir" usr

# ---- 6. Debian package -------------------------------------------------
if have dpkg-deb; then
    echo "==> deb package"
    deb_tree="$work_dir/deb-root"
    mkdir -p "$deb_tree/DEBIAN"
    cp -a "$stage_dir/usr" "$deb_tree/"
    install -d "$deb_tree/usr/share/doc/battuta"
    install -m 0644 "$repo_root/LICENSE" "$deb_tree/usr/share/doc/battuta/copyright"

    sed -e "s|@RELEASE_VERSION@|$VERSION|g" \
        -e "s|@INSTALLED_SIZE_KB@|$installed_size_kb|g" \
        "$packaging_root/debian/control" > "$deb_tree/DEBIAN/control"
    for maintainer_script in postinst prerm postrm; do
        install -m 0755 "$packaging_root/debian/$maintainer_script" "$deb_tree/DEBIAN/$maintainer_script"
    done
    dpkg-deb --root-owner-group --build "$deb_tree" "$out_dir/battuta_${VERSION}_amd64.deb" >/dev/null
    rm -rf "$deb_tree"
else
    echo "!! dpkg-deb missing — skipping deb (install the 'dpkg' tooling to build it)"
fi

# ---- 7. RPM package ----------------------------------------------------
# RPM versions must not contain '-'; a prerelease suffix ("0.9.0-rc1")
# becomes the release marker 0.1.rc1 so `rpm -V` ordering stays sane.
rpm_version="${VERSION%%-*}"
if [[ "$rpm_version" == "$VERSION" ]]; then
    rpm_release="1"
else
    rpm_prerelease="${VERSION#*-}"
    rpm_release="0.1.${rpm_prerelease//[^0-9A-Za-z.]/.}"
fi
if have rpmbuild; then
    echo "==> rpm package (version $rpm_version, release $rpm_release)"
    rpm_top="$work_dir/rpmbuild"
    mkdir -p "$rpm_top/SOURCES" "$rpm_top/SPECS" "$rpm_top/RPMS" "$rpm_top/BUILD" "$rpm_top/BUILDROOT"
    cp "$payload_tar" "$rpm_top/SOURCES/battuta-payload.tar.gz"
    sed -e "s|@RPM_VERSION@|$rpm_version|g" \
        -e "s|@RPM_RELEASE@|$rpm_release|g" \
        "$packaging_root/rpm/battuta.spec" > "$rpm_top/SPECS/battuta.spec"
    rpmbuild -bb --quiet \
        --define "_topdir $rpm_top" \
        "$rpm_top/SPECS/battuta.spec"
    find "$rpm_top/RPMS" -name '*.rpm' -exec mv {} "$out_dir/" \;
    rm -rf "$rpm_top"
else
    echo "!! rpmbuild missing — skipping rpm (install the 'rpm' tooling to build it)"
fi

# ---- 8. SBOM -----------------------------------------------------------
echo "==> SBOM"
node "$linux_root/scripts/generate-sbom.mjs" "$VERSION" \
    "$out_dir/Battuta-Linux-$VERSION-linux-x64.spdx.json"

# ---- 9. Checksums and optional signing ---------------------------------
echo "==> SHA-256 checksums"
artifacts=(
    "Battuta-Linux-$VERSION-linux-x64.tar.gz"
    "Battuta-Linux-$VERSION-linux-x64.spdx.json"
)
[[ -f "$out_dir/battuta_${VERSION}_amd64.deb" ]] && artifacts+=("battuta_${VERSION}_amd64.deb")
rpm_file="$(cd "$out_dir" && ls -1 "battuta-$rpm_version-$rpm_release"*.x86_64.rpm 2>/dev/null | head -n 1 || true)"
[[ -n "$rpm_file" ]] && artifacts+=("$rpm_file")
: > "$out_dir/SHA256SUMS"
for artifact in "${artifacts[@]}"; do
    (cd "$out_dir" && sha256sum "$artifact") >> "$out_dir/SHA256SUMS"
done

if [[ -n "${BATTUTA_RELEASE_SIGN_KEY:-}" ]]; then
    echo "==> GPG signatures (key: $BATTUTA_RELEASE_SIGN_KEY)"
    for signed in SHA256SUMS "${artifacts[@]}"; do
        gpg --batch --yes --local-user "$BATTUTA_RELEASE_SIGN_KEY" \
            --armor --detach-sign --output "$out_dir/$signed.asc" "$out_dir/$signed"
    done
else
    echo "!! BATTUTA_RELEASE_SIGN_KEY unset — artifacts left unsigned"
fi

echo "==> done. Artifacts in $out_dir:"
for artifact in "$out_dir"/*; do
    [[ -f "$artifact" ]] || continue
    printf '   %s (%s)\n' "$(basename "$artifact")" "$(du -h "$artifact" | cut -f1)"
done
